// Alt bilgiyi AJAN DEGIL BU DUGUM yaziyor.
// Sebep olculdu: 10 maddelik cevaplarda model bu satiri atliyor, 5 maddelikte
// yaziyor - uzun uretimde talimat soniyor. Metin sabit oldugu icin uretmesi
// gereken yer model degil kod.
//
// GIRDI ARTIK AJANDAN DEGIL, "Adlari Dogrula" POSTGRES DUGUMUNDEN GELIYOR.
// Cevap metni bu yuzden $input'tan degil dogrudan ajandan okunuyor - ajan ana
// akisin parcasi oldugu icin $() ile erisilebiliyor.
const cevap = String($('DS21 Ajan').first().json.output ?? '').trimEnd();

// Model yine de yazmis olabilir; tekrari onlemek icin kendi surumunu kes.
// Eski bicim "_Yuzde, ...", yeni bicim "_%, ..." - IKISI de kesiliyor.
const govde = cevap.replace(/\n*_(Yuzde|%),[\s\S]*$/, '').trimEnd();

// `_tani` kullaniciya GITMEZ: gecit yalnizca `output` alanini okuyor
// (gecit.js:178). Kapinin neyi gordugunu calisma kayitlarindan okumak icin.
const tani = [];

// ---- KURULUM UYDURMA KAPISI (12.09) ------------------------------------
// Bu chatbotun bicimi madde listesidir; kod bloku URETMEZ. Olculdu
// (calisma 61627 ve 61646): "nasil kurarim" sorusunda model HIC arama
// yapmadan `pip install -r requirements.txt`, `config.py`, `python app.py`
// ve `localhost:5000` adimlarini uydurdu - oysa o repo kendi tanimina gore
// Docker ve FastAPI ile kuruluyor. Isteme kural eklemek ise yaramadi, bu
// yuzden kapiyi KOD tutuyor: kod bloku varsa cevap komple degistirilir.
if (govde.indexOf('```') !== -1) {
  return [{ json: { _tani: 'kodbloku', output:
    'Kurulum adımlarını bilmiyorum: elimde reponun GitHub açıklaması ve terk ' +
    'tahmini var, README içeriği yok. Uydurmamak için adım vermiyorum - ' +
    'kurulum için reponun GitHub sayfasındaki README dosyasına bak.\n\n' +
    'İstersen aynı işi yapan başka repoları, güncel kalma ihtimalleriyle ' +
    'birlikte sıralayabilirim.' } }];
}

// ---- UYDURMA REPO KAPISI (12.09) ---------------------------------------
// Olculdu (calisma 62002): gercek bir kullanici "yasca en eski repo hangisi?"
// diye sordu. YAS verisi elimizde YOK - metadata yalnizca kategori, rozet,
// olgunluk, dil, aktiflik ve yildiz tutuyor. Model `sayim` aracini cagirdi,
// arac sadece kategori sayilari dondurdu, model de cevabi UYDURDU:
// veritabaninda BULUNMAYAN "japgolly/scala-arm" reposunu "1997'de kurulmus"
// diye sundu ve TAVSIYE ETTI. GitHub 2008'de kuruldu, yani tarih de imkansiz.
// Ustune kod tarafindan eklenen rozet uyarisi ve alt bilgi de gittigi icin
// uydurma cevap DOGRULANMIS gibi gorundu.
// Isteme "repo adi UYDURMA" kurali ZATEN yaziliydi ve tutmadi.
//
// ⚠️ ILK TASARIM OLCULEREK CURUTULDU: kapi once "bu turda araclardan hangi
// repolar dondu" diye soruyordu. Canli olcum (calisma 62011) gosterdi ki
// arac dugumlerinin ciktisi ana akistaki bir Code dugumunden OKUNAMIYOR -
// $('sayim').all() hata veriyor, cunku arac ciktisi `main` degil `ai_tool`
// dalinda. Sonuc: mesru repo listesi hep bos kalir ve kapi GitHub baglantisi
// iceren HER cevabi keserdi. Yani urunu komple bozacakti.
// Yetke bu yuzden ARSIVIN KENDISI: "Adlari Dogrula" dugumu, cevap metninin
// icinde gecen GERCEK repo adlarini veritabanina sorar (20 ms olculdu).
// DEGISMEZ: cevapta baglanti verilen her repo, arsivde BULUNAN bir repodur.
const dogrulama = $input.first().json || {};
const dayanakVar = typeof dogrulama.bulunan === 'string';
const arsivde = new Set(
  dayanakVar ? String(dogrulama.bulunan).toLowerCase().split(/\s+/).filter(Boolean) : []
);
tani.push(dayanakVar ? 'dogrula=' + arsivde.size : 'dogrula=DAYANAK_YOK');

const BAGLANTI = /github\.com\/([A-Za-z0-9._-]+\/[A-Za-z0-9._-]+)/gi;
const gecen = new Set();
let eslesme;
while ((eslesme = BAGLANTI.exec(govde)) !== null) gecen.add(eslesme[1].toLowerCase());
const disi = [...gecen].filter(r => !arsivde.has(r));

// DAYANAK SARTI: dogrulama dugumu calismadiysa (veritabani dustu, dugum hata
// verdi) kapi SESSIZ kalir. Yanlis yere kapanmak, calisan bir cevabi yok
// etmek demektir ve juri onunde bu daha kotudur.
if (dayanakVar && disi.length) {
  return [{ json: {
    _tani: tani.join(' ') + ' | KAPANDI: ' + disi.join(','),
    output:
      'Bu cevabı göndermiyorum: taslakta arşivimde bulunmayan bir repo adı ' +
      'vardı. Arşivde 24 binden fazla repo var ama dışına çıkıp tahmin ' +
      'üretmem - yanlış bir repo önermektense bilmediğimi söylerim.\n\n' +
      'Ne aradığını bir cümleyle anlatırsan arşivden arayıp güncel kalma ' +
      'ihtimalleriyle birlikte getirebilirim.'
  } }];
}

// ---- KAPI (11.09) - alt bilgi ARTIK HER CEVABA EKLENMIYOR --------------
// Olculdu (57 gercek calisma kaydi): 12'sinde aciklanacak bir sey yoktu -
// selamlasma, sayim istatistigi, "neler yapabilirsin", sonuc bulunamadi.
// Ornek: calisma 60734, soru "Merhaba nasilsin?", cevap 100 karakter,
// arkasina 371 karakterlik alt bilgi eklenmisti.
//
// DEGISMEZ: alt bilgi ROZETI ve YUZDEYI aciklar. Kapi da onu arar -
// "repodan bahsetti mi" degil, "rozet ya da yuzde GOSTERDI mi".
const REPO_LINKI = /\]\(https:\/\/github\.com\/[^)\s]+\)/;
const ROZET      = /[\u{1F7E2}\u{1F7E1}\u{1F534}]/u;
const YUZDE      = /%\s?\d/;

if (!REPO_LINKI.test(govde) || !(ROZET.test(govde) || YUZDE.test(govde))) {
  return [{ json: { output: govde, _tani: tani.join(' ') } }];
}

// Etiket C sozlesmesi: varsayilan dala ULASAN degisiklik. Bu cumle
// model.pkl icindeki LABEL_WORDING["etiket_c"]["urun_uzun"] ile ayni seyi
// soyler; biri degisirse digeri de degismeli.
const alt = '_%, önümüzdeki 6 ayda reponun varsayılan dalına en az bir ' +
            'değişikliğin ulaşma olasılığıdır. ' +
            '🟢 ≥%60 · 🟡 %30-60 · 🔴 <%30_';

return [{ json: { output: govde + '\n\n' + alt, _tani: tani.join(' ') } }];
